html,body{height:100%;margin:0}#dc-root,#dc-root>.sc-host{height:100%}

    body { margin:0; background:#100F0F; -webkit-font-smoothing:antialiased; }
    a { color:#E4E24E; text-decoration:none; }
    a:hover { color:#E4E24E; text-decoration:underline; }
    @keyframes kenburns { 0% { transform:scale(1); } 100% { transform:scale(1.06); } }
    @keyframes fadeUp { from { opacity:0; transform:translateY(8px); } to { opacity:1; transform:translateY(0); } }
    @keyframes revealUp { from { opacity:0; transform:translateY(24px); } to { opacity:1; transform:translateY(0); } }
    @supports (animation-timeline: view()) {
      [data-reveal] { animation:revealUp 700ms cubic-bezier(0.2,0.8,0.2,1) both; animation-timeline:view(); animation-range:entry 0% cover 22%; }
    }
    html { scrollbar-width:none; }
    html::-webkit-scrollbar, body::-webkit-scrollbar { width:0; height:0; display:none; }
    [data-nav] { transition:background 400ms; }
    [data-nav] a { transition:color 250ms, background 150ms, border-color 250ms, filter 150ms; }
    [data-nav][data-theme="dark"] { background:#100F0F !important; }
    [data-nav][data-theme="photo"] { background:transparent !important; }
    [data-nav][data-theme="light"] { background:#FAFAF7 !important; }
    [data-nav][data-theme="cream"] { background:#F4F1EB !important; }
    [data-nav][data-theme="light"] a, [data-nav][data-theme="cream"] a { color:#100F0F !important; }
    [data-nav][data-theme="light"] a[data-navcta], [data-nav][data-theme="cream"] a[data-navcta] { border-color:rgba(16,15,15,0.4) !important; }
    @media (max-width: 1000px) {
      [data-tphoto="c"], [data-tphoto="d"] { display:none !important; }
      [data-tphoto="a"], [data-tphoto="b"] { width:130px !important; height:150px !important; }
      [data-mob="chapter"] { max-width:100% !important; }
      [data-mob="trustL"] { border-right:none !important; padding:8px 0 32px !important; border-bottom:3px double rgba(16,15,15,0.25) !important; }
      [data-mob="trustR"] { padding:32px 0 8px !important; }
    }
    @media (max-width: 760px) {
      [data-mob="navlinks"], [data-mob="login"] { display:none !important; }
      [data-mob="ticker2"], [data-mob="ticker3"] { display:none !important; }
      [data-mob="chapter"] { padding:80px 24px !important; }
    }
    @media (pointer: coarse) {
      html { scroll-snap-type:y mandatory; }
      [data-snap] { scroll-snap-align:start; }
    }

